out=[[0]*26 for _ in range(22)]
for r0,r1,c0,c1,border,fill in [(1,6,3,11,1,4),(10,13,2,5,2,8),(9,16,11,21,3,5)]:
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if r in (r0,r1) or c in (c0,c1): out[r][c]=border
            elif (r-r0-1+c-c0-1)%2==0: out[r][c]=fill
print('\n'.join(' '.join(map(str,r)) for r in out))
